UPDATE dashboard_templates SET definition = '{"schemaVersion":1,"widgets":[{"title":"Largest Contentful Paint","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"p75","label":"p75"},{"type":"metric","name":"browser.web_vital.lcp","aggregation":"p95","label":"p95"}]}},{"title":"Interaction to Next Paint","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.inp","aggregation":"p75","label":"p75"},{"type":"metric","name":"browser.web_vital.inp","aggregation":"p95","label":"p95"}]}},{"title":"Cumulative Layout Shift","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.cls","aggregation":"p75","label":"p75"},{"type":"metric","name":"browser.web_vital.cls","aggregation":"p95","label":"p95"}]}},{"title":"LCP Ratings","widgetType":"rating_bar","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"count","groupBy":"rating"}]}},{"title":"INP Ratings","widgetType":"rating_bar","config":{"sources":[{"type":"metric","name":"browser.web_vital.inp","aggregation":"count","groupBy":"rating"}]}},{"title":"CLS Ratings","widgetType":"rating_bar","config":{"sources":[{"type":"metric","name":"browser.web_vital.cls","aggregation":"count","groupBy":"rating"}]}},{"title":"First Contentful Paint","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.fcp","aggregation":"p75","label":"p75"}]}},{"title":"Time to First Byte","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.ttfb","aggregation":"p75","label":"p75"}]}},{"title":"Page Load","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.page_load.duration","aggregation":"p75","label":"Load event"},{"type":"metric","name":"browser.page_load.dom_content_loaded","aggregation":"p75","label":"DOM content loaded"}]}},{"title":"LCP by Release","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"p75","groupBy":"service.version","label":"p75"}]}},{"title":"LCP by Browser","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"p75","groupBy":"browser.name","label":"p75"}]}},{"title":"LCP by Page","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"browser.web_vital.lcp","aggregation":"p75","groupBy":"url.path","label":"p75"}]}},{"title":"Route Change Duration","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.route_timing.duration","aggregation":"p75","label":"p75"},{"type":"metric","name":"browser.route_timing.duration","aggregation":"p95","label":"p95"}]}},{"title":"Route Change Duration by Page","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"browser.route_timing.duration","aggregation":"p75","groupBy":"url.path","label":"p75"}]}},{"title":"Blocking Time per Page View","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.long_task.blocking_time","aggregation":"p75","label":"p75"},{"type":"metric","name":"browser.long_task.blocking_time","aggregation":"p95","label":"p95"}]}},{"title":"Long Tasks","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.long_task.duration","aggregation":"count","label":"Blocks of 50 ms or more"}]}},{"title":"Longest Main-Thread Block","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.long_task.duration","aggregation":"max","label":"Longest"}]}},{"title":"Long Tasks by Page","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"browser.long_task.duration","aggregation":"p95","groupBy":"url.path","label":"p95"}]}},{"title":"Request Duration by Host","widgetType":"breakdown_table","config":{"sources":[{"type":"metric","name":"browser.request.duration","aggregation":"p75","groupBy":"host","label":"p75"}]}},{"title":"Page Views","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.page_view","aggregation":"sum","label":"Page views"},{"type":"metric","name":"browser.session","aggregation":"sum","label":"Sessions"}]}},{"title":"JavaScript Errors","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"browser.js_error","aggregation":"sum","label":"Errors"},{"type":"metric","name":"browser.rage_click","aggregation":"sum","label":"Rage clicks"}]}}]}', description = 'Web vitals, route changes, main-thread blocking, requests and page load, as percentiles over every page view', updated_at = datetime('now') WHERE key = 'browser-performance';
